//! Every configuration key in `config.toml`, as constants: one [`KeyDef`] per key and
//! the [`KEYS`] table. Generated by `scripts/gen-config.py`; do not edit. Change
//! `config.toml` and run `just gen-config`; `just lint-config` fails while this file
//! is stale (ADR 0020).

use super::{KeyDef, Kind};

/// `dir`, path: The driver directory: where the driver creates its counters file, command ring, broadcast buffer and log buffers, and where clients and doctor find it (spec/client-protocol.md, The driver directory). A relative path is relative to the working directory of the process that reads it.
pub const DIR: KeyDef = KeyDef {
    name: "dir",
    env: "CAVALRY_DIR",
    flag: Some("--dir"),
    kind: Kind::Path,
    values: &[],
    default: "cavalry-<user> under /dev/shm on Linux when /dev/shm exists, else under the temporary directory",
    term: "driver directory",
    doc: "The driver directory: where the driver creates its counters file, command ring, broadcast buffer and log buffers, and where clients and doctor find it (spec/client-protocol.md, The driver directory). A relative path is relative to the working directory of the process that reads it.",
    why_not_default: "One directory per host and user is right on a laptop and on a cloud VM, and wrong for two drivers on one host, for a container whose /dev/shm is 64 MiB or absent, and for a host whose memory-backed filesystem is mounted elsewhere; the default cannot know which host it is on.",
    doctor: "driver-directory-backing",
    anchor: "docs/reference/config.md#dir",
};

/// `conductor.idle.strategy`, one of backoff, yield, busy-spin: What the conductor's thread does on a duty cycle that found no work: backoff spins, then yields, then sleeps for longer and longer up to 1 ms; yield gives the CPU up on every idle cycle; busy-spin never leaves the CPU. The running driver records its choice in the conductor.idle_strategy counter.
pub const CONDUCTOR_IDLE_STRATEGY: KeyDef = KeyDef {
    name: "conductor.idle.strategy",
    env: "CAVALRY_CONDUCTOR_IDLE_STRATEGY",
    flag: None,
    kind: Kind::Enum,
    values: &["backoff", "yield", "busy-spin"],
    default: "backoff",
    term: "idle strategy",
    doc: "What the conductor's thread does on a duty cycle that found no work: backoff spins, then yields, then sleeps for longer and longer up to 1 ms; yield gives the CPU up on every idle cycle; busy-spin never leaves the CPU. The running driver records its choice in the conductor.idle_strategy counter.",
    why_not_default: "Backoff is right on a laptop and on a cloud VM, where a spinning conductor would take a core from the clients; busy-spin is right on an isolated core, where backoff's sleep of up to 1 ms delays the limit a publisher waits on; the driver cannot tell from inside which core it was given.",
    doctor: "conductor-idle-strategy",
    anchor: "docs/reference/config.md#conductoridlestrategy",
};

/// `log.dir`, path: The log directory: where the driver's recorder writes the durable log, the catalog, the segment files and the time indexes, on disk and never under the driver directory, held under an advisory lock by one driver at a time (spec/durable-log.md); run, doctor and record read it. Its path is at most 337 bytes, so that a segment roll opens its file on the standard library's stack buffer instead of allocating on the recorder thread; doctor warns on a longer one.
pub const LOG_DIR: KeyDef = KeyDef {
    name: "log.dir",
    env: "CAVALRY_LOG_DIR",
    flag: Some("--log-dir"),
    kind: Kind::Path,
    values: &[],
    default: "cavalry/log under $XDG_DATA_HOME when that variable is set, else ~/.local/share/cavalry/log, and /var/lib/cavalry/log when the driver runs as root; with neither a home nor root the driver refuses to start and names this key",
    term: "log directory",
    doc: "The log directory: where the driver's recorder writes the durable log, the catalog, the segment files and the time indexes, on disk and never under the driver directory, held under an advisory lock by one driver at a time (spec/durable-log.md); run, doctor and record read it. Its path is at most 337 bytes, so that a segment roll opens its file on the standard library's stack buffer instead of allocating on the recorder thread; doctor warns on a longer one.",
    why_not_default: "The home filesystem can be small, a network mount where a sync and a lock mean little, or absent for a service user; a container's is ephemeral; the operator usually wants the log on a disk chosen for room and durability, which the driver cannot pick.",
    doctor: "log-directory-backing",
    anchor: "docs/reference/config.md#logdir",
};

/// `cluster.members`, string: The members string of the cluster this driver is a member of: `id,ingress,consensus,log,catchup,archive` for each member, an id and five `host:port` endpoints, members separated by `|` (spec/cluster.md, Members and streams). Every member of a cluster is given the same string. Set together with cluster.member.id, it makes `cavalry run` start the member's consensus module beside the driver.
pub const CLUSTER_MEMBERS: KeyDef = KeyDef {
    name: "cluster.members",
    env: "CAVALRY_CLUSTER_MEMBERS",
    flag: None,
    kind: Kind::String,
    values: &[],
    default: "empty, which is no cluster: the driver runs as it does without one",
    term: "members string",
    doc: "The members string of the cluster this driver is a member of: `id,ingress,consensus,log,catchup,archive` for each member, an id and five `host:port` endpoints, members separated by `|` (spec/cluster.md, Members and streams). Every member of a cluster is given the same string. Set together with cluster.member.id, it makes `cavalry run` start the member's consensus module beside the driver.",
    why_not_default: "A cluster is the hosts an operator chose, and each member's five endpoints are addresses on those hosts; a driver cannot find them from inside, and one that guessed would join a cluster it was not meant for.",
    doctor: "cluster-members",
    anchor: "docs/reference/config.md#clustermembers",
};

/// `cluster.member.id`, integer: This driver's member id in cluster.members: which of the string's members `cavalry run` starts on this host, a whole number from 0 to 2147483647. -1, the default, is no member, the same as the key unset, so that a unit file may write the default out; any other value is refused before anything starts. The member with the lowest id is the cluster's appointed leader (spec/cluster.md, The appointed leader).
pub const CLUSTER_MEMBER_ID: KeyDef = KeyDef {
    name: "cluster.member.id",
    env: "CAVALRY_CLUSTER_MEMBER_ID",
    flag: None,
    kind: Kind::Integer,
    values: &[],
    default: "-1, which is no member",
    term: "member",
    doc: "This driver's member id in cluster.members: which of the string's members `cavalry run` starts on this host, a whole number from 0 to 2147483647. -1, the default, is no member, the same as the key unset, so that a unit file may write the default out; any other value is refused before anything starts. The member with the lowest id is the cluster's appointed leader (spec/cluster.md, The appointed leader).",
    why_not_default: "Every member of a cluster holds the same members string, so the id alone says which member a host is; no default is right on more than one of them.",
    doctor: "cluster-member-id",
    anchor: "docs/reference/config.md#clustermemberid",
};

/// Every key of `config.toml`, in the file's order.
pub const KEYS: &[&KeyDef] = &[
    &DIR,
    &CONDUCTOR_IDLE_STRATEGY,
    &LOG_DIR,
    &CLUSTER_MEMBERS,
    &CLUSTER_MEMBER_ID,
];
